window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-816c4e80a018ebd9"]={"versions": [{"id": "FIG-816c4e80a018ebd9", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von analogen Ein-/Ausgabe-Peripherien (<code>AnalogueIO</code>) im Rahmen des ECU-Ressourcen-Templates (<code>AUTOSAR_ResourceTemplateECU</code>). Es beschreibt die statische Metamodellstruktur für Analog-Digital- und Digital-Analog-Wandler (<code>ADC</code>, <code>DAC</code>) sowie deren elektrische Referenzierungs- und Betriebscharakteristika.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>AnalogueIO</code></strong> (Stereotyp bzw. Paketvermerk <code>Peripheral</code>): Zentrale Basisklasse mit Attributen:</li>\n<li><code>resolution: Int</code></li>\n<li><code>accuracy: Float</code></li>\n<li><code>mode: Enumeration{continuous, single, sequential}</code></li>\n<li><code>width: Int</code></li>\n<li><code>conversionTime: Float [0..1]</code></li>\n<li><code>multiplexedN: Int [0..1]</code></li>\n<li><code>multiplexedM: Int [0..1]</code></li>\n<li><strong><code>ElectricalRange</code></strong>: Beschreibt elektrische Grenz- und Nennwerte mit den Attributen:</li>\n<li><code>minVoltage: Float</code></li>\n<li><code>maxVoltage: Float</code></li>\n<li><code>typicalVoltage: Float [0..1]</code></li>\n<li><code>minCurrent: Float [0..1]</code></li>\n<li><code>maxCurrent: Float [0..1]</code></li>\n<li><code>typicalCurrent: Float [0..1]</code></li>\n<li><strong><code>ADC</code></strong>: Spezialisierung (Generalisierungsbeziehung zu <code>AnalogueIO</code>) für Analog-Digital-Wandler mit dem Attribut:</li>\n<li><code>behaviourAtLimit: Enumeration{clipping, default, undefined, other}</code></li>\n<li><strong><code>DAC</code></strong>: Spezialisierung (Generalisierungsbeziehung zu <code>AnalogueIO</code>) für Digital-Analog-Wandler ohne eigene Attribute.</li>\n<li><strong>Kompositionsbeziehung</strong>: <code>AnalogueIO</code> bindet über eine Komposition mit der Rollenbezeichnung <code>+EXTERNAL-REFERENCE-VOLTAGE</code> und der Kardinalität <code>0..1</code> eine Instanz von <code>ElectricalRange</code> ein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als Struktur- und Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Zustandsübergänge oder Laufzeitsequenzen dar. Die Erfassungs- bzw. Ausgabemodi (<code>continuous</code>, <code>single</code>, <code>sequential</code>) sowie Zeitparameter (<code>conversionTime</code>) spezifizieren statische Konfigurationsmerkmale für die Ausführung der Analogwandlung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Konfiguration und Beschreibung der Hardware-Fähigkeiten eines Steuergeräts im AUTOSAR ECU Resource Template. Pflichtattribute von <code>AnalogueIO</code> (<code>resolution</code>, <code>accuracy</code>, <code>mode</code>, <code>width</code>) sowie <code>minVoltage</code> und <code>maxVoltage</code> in <code>ElectricalRange</code> müssen bei Instanziierung belegt werden; Multiplexing-Faktoren, Konvertierungszeit und Ströme sind optional (<code>[0..1]</code>). Die Grenzbehandlung von ADC-Eingängen ist über die Enumerationswerte von <code>behaviourAtLimit</code> typisiert.</p>"}, {"id": "FIG-3dca52b86b6903a0", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von analogen Ein-/Ausgabe-Peripherien (<code>AnalogueIO</code>) im Rahmen des ECU-Ressourcen-Templates (<code>AUTOSAR_ResourceTemplateECU</code>). Es beschreibt die statische Metamodellstruktur für Analog-Digital- und Digital-Analog-Wandler (<code>ADC</code>, <code>DAC</code>) sowie deren elektrische Referenzierungs- und Betriebscharakteristika.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>AnalogueIO</code></strong> (Stereotyp bzw. Paketvermerk <code>Peripheral</code>): Zentrale Basisklasse mit Attributen:</li>\n<li><code>resolution: Int</code></li>\n<li><code>accuracy: Float</code></li>\n<li><code>mode: Enumeration{continuous, single, sequential}</code></li>\n<li><code>width: Int</code></li>\n<li><code>conversionTime: Float [0..1]</code></li>\n<li><code>multiplexedN: Int [0..1]</code></li>\n<li><code>multiplexedM: Int [0..1]</code></li>\n<li><strong><code>ElectricalRange</code></strong>: Beschreibt elektrische Grenz- und Nennwerte mit den Attributen:</li>\n<li><code>minVoltage: Float</code></li>\n<li><code>maxVoltage: Float</code></li>\n<li><code>typicalVoltage: Float [0..1]</code></li>\n<li><code>minCurrent: Float [0..1]</code></li>\n<li><code>maxCurrent: Float [0..1]</code></li>\n<li><code>typicalCurrent: Float [0..1]</code></li>\n<li><strong><code>ADC</code></strong>: Spezialisierung (Generalisierungsbeziehung zu <code>AnalogueIO</code>) für Analog-Digital-Wandler mit dem Attribut:</li>\n<li><code>behaviourAtLimit: Enumeration{clipping, default, undefined, other}</code></li>\n<li><strong><code>DAC</code></strong>: Spezialisierung (Generalisierungsbeziehung zu <code>AnalogueIO</code>) für Digital-Analog-Wandler ohne eigene Attribute.</li>\n<li><strong>Kompositionsbeziehung</strong>: <code>AnalogueIO</code> bindet über eine Komposition mit der Rollenbezeichnung <code>+EXTERNAL-REFERENCE-VOLTAGE</code> und der Kardinalität <code>0..1</code> eine Instanz von <code>ElectricalRange</code> ein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als Struktur- und Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Zustandsübergänge oder Laufzeitsequenzen dar. Die Erfassungs- bzw. Ausgabemodi (<code>continuous</code>, <code>single</code>, <code>sequential</code>) sowie Zeitparameter (<code>conversionTime</code>) spezifizieren statische Konfigurationsmerkmale für die Ausführung der Analogwandlung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Konfiguration und Beschreibung der Hardware-Fähigkeiten eines Steuergeräts im AUTOSAR ECU Resource Template. Pflichtattribute von <code>AnalogueIO</code> (<code>resolution</code>, <code>accuracy</code>, <code>mode</code>, <code>width</code>) sowie <code>minVoltage</code> und <code>maxVoltage</code> in <code>ElectricalRange</code> müssen bei Instanziierung belegt werden; Multiplexing-Faktoren, Konvertierungszeit und Ströme sind optional (<code>[0..1]</code>). Die Grenzbehandlung von ADC-Eingängen ist über die Enumerationswerte von <code>behaviourAtLimit</code> typisiert.</p>"}], "trans": [{"from": "FIG-816c4e80a018ebd9", "to": "FIG-3dca52b86b6903a0", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
